#!/usr/bin/env python3
"""
Permission Manager for MintPilot on Linux Mint
Enables dual operational modes:
- Turbo Mode (Antigravity-Style): Full autonomy, zero permission prompts, continuous self-healing execution.
- Safe Mode: Intercepts sensitive operations (shell commands, file alterations, browser actions, system power)
  and requests explicit user confirmation before completing tasks.
"""

import os
import json
from pathlib import Path
from typing import Dict, Any, Optional, Callable

CONFIG_PATH = Path(__file__).resolve().parent.parent / "config" / "settings.json"


class PermissionManager:
    """Controls action authorization policies and permission modes."""

    # Sensitive operations requiring approval in Safe Mode
    SENSITIVE_ACTIONS = [
        "terminal_execute",
        "install_packages",
        "power_action",
        "kill_process",
        "browser_click",
        "browser_fill",
        "program_save",
        "file_write",
        "file_delete"
    ]

    def __init__(self, mode: Optional[str] = None):
        self.config_path = CONFIG_PATH
        self.mode = mode or self._load_mode_from_config()
        self.pending_approvals: Dict[str, Dict[str, Any]] = {}
        self._approval_callback: Optional[Callable[[Dict[str, Any]], bool]] = None

    def _load_mode_from_config(self) -> str:
        """Loads mode from settings.json; defaults to 'turbo' if absent."""
        if self.config_path.exists():
            try:
                with open(self.config_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    return data.get("mode", "turbo").lower()
            except Exception:
                pass
        return "turbo"

    def set_mode(self, mode: str) -> str:
        """Updates mode ('turbo' or 'safe') and persists to configuration."""
        clean_mode = mode.lower().strip()
        if clean_mode not in ["turbo", "safe"]:
            raise ValueError(f"Invalid mode '{mode}'. Must be 'turbo' or 'safe'.")

        self.mode = clean_mode

        # Persist to settings.json
        if self.config_path.exists():
            try:
                with open(self.config_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                data["mode"] = self.mode
                with open(self.config_path, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=2)
            except Exception:
                pass

        return self.mode

    def is_turbo(self) -> bool:
        """Returns True if running in unrestricted autonomous Turbo Mode."""
        return self.mode == "turbo"

    def register_approval_callback(self, callback: Callable[[Dict[str, Any]], bool]):
        """Registers a UI or CLI callback handler to prompt the user for approval."""
        self._approval_callback = callback

    def check_permission(self, action_type: str, details: Dict[str, Any], prompt_cli: bool = False) -> Dict[str, Any]:
        """
        Evaluates whether the proposed action is permitted to execute.
        Returns:
          {"allowed": True} or {"allowed": False, "reason": "Requires user approval", "pending_id": ...}
        """
        # In Turbo Mode, everything is permitted immediately
        if self.is_turbo():
            return {
                "allowed": True,
                "mode": "turbo",
                "notice": "Autonomous Turbo Mode active: Executed without prompts."
            }

        # In Safe Mode, check if action is sensitive
        is_sensitive = action_type in self.SENSITIVE_ACTIONS or details.get("is_sensitive", False)

        if not is_sensitive:
            return {"allowed": True, "mode": "safe", "notice": "Non-sensitive read-only operation."}

        # Sensitive action in Safe Mode: Needs Approval
        action_id = f"act_{len(self.pending_approvals) + 1}_{action_type}"
        record = {
            "id": action_id,
            "action_type": action_type,
            "details": details,
            "status": "pending"
        }
        self.pending_approvals[action_id] = record

        # If a UI callback is registered, trigger it
        if self._approval_callback:
            approved = self._approval_callback(record)
            if approved:
                record["status"] = "approved"
                return {"allowed": True, "mode": "safe", "approved_by": "user_ui"}
            else:
                record["status"] = "rejected"
                return {"allowed": False, "reason": "User denied action in UI.", "mode": "safe"}

        # If CLI interactive prompt requested
        if prompt_cli:
            print(f"\n\033[1;33m[SAFE MODE PERMISSION REQUEST]\033[0m")
            print(f"Action: \033[1;36m{action_type}\033[0m")
            print(f"Details: {json.dumps(details, indent=2)}")
            try:
                ans = input("Approve this action? (y/N): ").strip().lower()
                if ans in ["y", "yes"]:
                    record["status"] = "approved"
                    return {"allowed": True, "mode": "safe", "approved_by": "cli_user"}
                else:
                    record["status"] = "rejected"
                    return {"allowed": False, "reason": "Action rejected by user.", "mode": "safe"}
            except (KeyboardInterrupt, EOFError):
                record["status"] = "rejected"
                return {"allowed": False, "reason": "Prompt aborted by user.", "mode": "safe"}

        # Pending approval (e.g. for WebUI modal poll)
        return {
            "allowed": False,
            "reason": "Safe Mode requires explicit user approval.",
            "mode": "safe",
            "pending_id": action_id,
            "action": record
        }

    def resolve_pending(self, action_id: str, approved: bool) -> bool:
        """Resolves a pending approval from WebUI or remote signal."""
        if action_id in self.pending_approvals:
            self.pending_approvals[action_id]["status"] = "approved" if approved else "rejected"
            return True
        return False

#!/usr/bin/env python3
"""
Browser Controller for MintPilot on Linux Mint
Enables deep browser automation both through native desktop GUI controls
(Firefox, Chrome, Chromium) and direct web content perception.
"""

import re
import time
import shutil
import urllib.request
import urllib.parse
import subprocess
from typing import Dict, Any, List, Optional

from agent.controllers.gui_control import GUIController


class BrowserController:
    """Automates and controls web browsers on Linux Mint."""

    SUPPORTED_BROWSERS = ["firefox", "google-chrome", "chromium-browser", "brave-browser"]

    def __init__(self, gui_controller: Optional[GUIController] = None):
        self.gui = gui_controller or GUIController()
        self.active_browser = self._detect_default_browser()

    def _detect_default_browser(self) -> str:
        """Finds the primary installed browser on the system."""
        for b in self.SUPPORTED_BROWSERS:
            if shutil.which(b):
                return b
        return "firefox"

    # ==================== NATIVE DESKTOP BROWSER CONTROL ====================

    def open_url_in_browser(self, url: str, new_tab: bool = True) -> Dict[str, Any]:
        """
        Opens a URL in the user's desktop browser (Firefox / Chrome).
        """
        if not url.startswith("http://") and not url.startswith("https://"):
            url = "https://" + url

        try:
            # Launch via xdg-open or direct browser
            subprocess.Popen(["xdg-open", url], start_new_session=True)
            time.sleep(1.2)
            return {
                "status": "success",
                "opened_url": url,
                "browser": self.active_browser,
                "action": "open_url"
            }
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def focus_browser(self) -> Dict[str, Any]:
        """Brings the active browser window to the foreground."""
        for b in ["Firefox", "Chrome", "Chromium", "Brave"]:
            res = self.gui.focus_window(b)
            if res.get("status") == "success":
                return {"status": "success", "focused_browser": b}
        return {"error": "No open browser window found to focus", "status": "failed"}

    def new_tab(self, url: Optional[str] = None) -> Dict[str, Any]:
        """Opens a new tab in the active browser, optionally navigating to a URL."""
        self.focus_browser()
        time.sleep(0.3)
        self.gui.hotkey("ctrl+t")
        time.sleep(0.3)

        if url:
            self.gui.type_text(url)
            time.sleep(0.1)
            self.gui.press_key("Return")

        return {"status": "success", "action": "new_tab", "url": url}

    def close_current_tab(self) -> Dict[str, Any]:
        """Closes the currently active browser tab."""
        self.focus_browser()
        time.sleep(0.2)
        self.gui.hotkey("ctrl+w")
        return {"status": "success", "action": "close_tab"}

    def switch_tab(self, direction: str = "next") -> Dict[str, Any]:
        """Switches to next or previous tab."""
        self.focus_browser()
        time.sleep(0.2)
        if direction.lower() in ["prev", "previous", "left"]:
            self.gui.hotkey("ctrl+Page_Up")
        else:
            self.gui.hotkey("ctrl+Page_Down")
        return {"status": "success", "action": f"switch_tab_{direction}"}

    def scroll_page(self, direction: str = "down", amount: int = 3) -> Dict[str, Any]:
        """Scrolls the current webpage up or down."""
        self.focus_browser()
        key = "Page_Down" if direction.lower() == "down" else "Page_Up"
        for _ in range(max(1, amount)):
            self.gui.press_key(key)
            time.sleep(0.15)
        return {"status": "success", "scrolled": direction, "times": amount}

    def search_web(self, query: str) -> Dict[str, Any]:
        """Performs a web search in the desktop browser."""
        encoded = urllib.parse.quote_plus(query)
        search_url = f"https://www.google.com/search?q={encoded}"
        return self.open_url_in_browser(search_url)

    # ==================== LIGHTWEIGHT CONTENT EXTRACTOR ====================

    def fetch_page_content(self, url: str) -> Dict[str, Any]:
        """
        Fetches web page content directly and extracts readable text & links.
        Extremely memory-efficient (<5MB RAM), ideal for 2GB-4GB laptops.
        """
        if not url.startswith("http://") and not url.startswith("https://"):
            url = "https://" + url

        try:
            req = urllib.request.Request(
                url,
                headers={"User-Agent": "Mozilla/5.0 (X11; Linux x86_64; rv:109.0) Gecko/20100101 Firefox/119.0"}
            )
            with urllib.request.urlopen(req, timeout=12) as response:
                html = response.read().decode("utf-8", errors="ignore")

            # Extract Title
            title_m = re.search(r"<title[^>]*>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
            title = title_m.group(1).strip() if title_m else "No Title"

            # Strip script, style, comments
            clean_html = re.sub(r"<(script|style|noscript)[^>]*>.*?</\1>", "", html, flags=re.IGNORECASE | re.DOTALL)
            clean_html = re.sub(r"<!--.*?-->", "", clean_html, flags=re.DOTALL)

            # Extract Links
            links = []
            for match in re.finditer(r'<a[^>]+href=["\'](https?://[^"\']+)["\'][^>]*>(.*?)</a>', clean_html, re.IGNORECASE):
                href, text = match.group(1), re.sub(r"<[^>]+>", "", match.group(2)).strip()
                if text and len(links) < 25:
                    links.append({"text": text, "url": href})

            # Convert to plain text
            text = re.sub(r"<[^>]+>", " ", clean_html)
            text = re.sub(r"\s+", " ", text).strip()

            snippet = text[:2500] + ("..." if len(text) > 2500 else "")

            return {
                "status": "success",
                "url": url,
                "title": title,
                "text_snippet": snippet,
                "links": links
            }
        except Exception as e:
            return {"error": str(e), "status": "failed", "url": url}

#!/usr/bin/env python3
"""
Program Controller for MintPilot on Linux Mint
Enables deep automation and control over installed desktop programs:
LibreOffice (Writer, Calc), VLC Media Player, Nemo File Manager,
Text Editors (Xed, VS Code), Calculator, and Terminal.
"""

import os
import time
import shutil
import subprocess
from typing import Dict, Any, List, Optional

from agent.controllers.gui_control import GUIController


class ProgramController:
    """Controls and automates Linux Mint desktop applications."""

    # Map of common software names to Linux executable binaries & window classes
    APP_REGISTRY = {
        "libreoffice_writer": {"bin": "libreoffice --writer", "win": "Writer", "desc": "LibreOffice Writer Document"},
        "libreoffice_calc": {"bin": "libreoffice --calc", "win": "Calc", "desc": "LibreOffice Calc Spreadsheet"},
        "vlc": {"bin": "vlc", "win": "VLC", "desc": "VLC Media Player"},
        "nemo": {"bin": "nemo", "win": "Nemo", "desc": "Nemo File Manager"},
        "terminal": {"bin": "x-terminal-emulator", "win": "Terminal", "desc": "Terminal Emulator"},
        "text_editor": {"bin": "xed", "win": "xed", "desc": "Xed Text Editor"},
        "calculator": {"bin": "gnome-calculator", "win": "Calculator", "desc": "GNOME Calculator"},
        "system_monitor": {"bin": "gnome-system-monitor", "win": "System Monitor", "desc": "System Monitor"},
        "gimp": {"bin": "gimp", "win": "GIMP", "desc": "GIMP Image Editor"}
    }

    def __init__(self, gui_controller: Optional[GUIController] = None):
        self.gui = gui_controller or GUIController()

    def launch_program(self, app_key_or_name: str, args: Optional[List[str]] = None) -> Dict[str, Any]:
        """Launches a desktop program and brings it to focus."""
        clean_key = app_key_or_name.lower().replace(" ", "_").strip()
        cmd = None
        win_title = None

        if clean_key in self.APP_REGISTRY:
            cmd = self.APP_REGISTRY[clean_key]["bin"]
            win_title = self.APP_REGISTRY[clean_key]["win"]
        else:
            # Custom binary
            cmd = app_key_or_name
            win_title = app_key_or_name

        full_cmd = [cmd]
        if args:
            full_cmd.extend(args)

        try:
            subprocess.Popen(" ".join(full_cmd), shell=True, start_new_session=True)
            time.sleep(1.0)
            if win_title:
                self.gui.focus_window(win_title)
            return {"status": "success", "program": app_key_or_name, "action": "launched"}
        except Exception as e:
            return {"error": str(e), "status": "failed"}

    def control_libreoffice_writer(self, text_to_write: str, save_path: Optional[str] = None) -> Dict[str, Any]:
        """
        Creates a new LibreOffice Writer document, types text into it, and saves if path is given.
        """
        self.launch_program("libreoffice_writer")
        time.sleep(2.0)  # Wait for Writer to initialize

        # Focus window
        self.gui.focus_window("Writer")
        time.sleep(0.5)

        # Type the text
        self.gui.type_text(text_to_write)
        time.sleep(0.5)

        if save_path:
            abs_path = os.path.abspath(os.path.expanduser(save_path))
            self.gui.hotkey("ctrl+s")
            time.sleep(0.8)
            self.gui.type_text(abs_path)
            time.sleep(0.3)
            self.gui.press_key("Return")
            return {"status": "success", "action": "written_and_saved", "file": abs_path}

        return {"status": "success", "action": "written_to_document"}

    def control_vlc(self, action: str, media_file: Optional[str] = None) -> Dict[str, Any]:
        """
        Controls VLC Media Player: play, pause, fullscreen, volume, or open file.
        """
        if media_file:
            path = os.path.abspath(os.path.expanduser(media_file))
            return self.launch_program("vlc", [path])

        self.gui.focus_window("VLC")
        time.sleep(0.2)

        act = action.lower().strip()
        if act in ["play", "pause", "toggle"]:
            self.gui.press_key("space")
        elif act in ["fullscreen", "toggle_fullscreen"]:
            self.gui.press_key("f")
        elif act in ["mute", "unmute"]:
            self.gui.press_key("m")
        elif act in ["stop"]:
            self.gui.press_key("s")
        elif act in ["forward", "seek_forward"]:
            self.gui.hotkey("alt+Right")
        elif act in ["backward", "seek_backward"]:
            self.gui.hotkey("alt+Left")
        else:
            return {"error": f"Unknown VLC action: '{action}'"}

        return {"status": "success", "action": f"vlc_{action}"}

    def open_directory_in_nemo(self, dir_path: str = "~") -> Dict[str, Any]:
        """Opens a folder path in Linux Mint's Nemo file manager."""
        target = os.path.abspath(os.path.expanduser(dir_path))
        return self.launch_program("nemo", [target])

    def close_program(self, app_name_or_window: str) -> Dict[str, Any]:
        """Closes a program window gracefully."""
        return self.gui.close_window(app_name_or_window)

    def list_running_programs(self) -> Dict[str, Any]:
        """Lists active desktop application windows with process information."""
        return self.gui.list_windows()

#!/usr/bin/env python3
"""
MintPilot Offline Autonomous Brain & Tool Router
Combines sub-millisecond fast deterministic intent routing,
permission control (Turbo vs Safe Mode), memory safeguards (2GB-4GB RAM),
browser automation, program control, and local SLM cognitive planning.
"""

import os
import re
import json
import time
import shutil
import subprocess
from typing import Dict, Any, List, Optional

from agent.core.permission_manager import PermissionManager
from agent.core.memory_guard import MemoryGuard
from agent.controllers.system_control import SystemController
from agent.controllers.gui_control import GUIController
from agent.controllers.terminal_control import TerminalController
from agent.controllers.screen_vision import ScreenVisionController
from agent.controllers.voice_engine import VoiceEngine
from agent.controllers.browser_control import BrowserController
from agent.controllers.program_control import ProgramController


class AgentBrain:
    """The central intelligence coordinating perception, planning, permissions, and execution."""

    def __init__(self, model_path: Optional[str] = None, mode: Optional[str] = None):
        # Core Managers
        self.permissions = PermissionManager(mode=mode)
        self.memory = MemoryGuard()

        # Controllers
        self.system = SystemController()
        self.gui = GUIController()
        self.terminal = TerminalController()
        self.vision = ScreenVisionController()
        self.voice = VoiceEngine()
        self.browser = BrowserController(self.gui)
        self.programs = ProgramController(self.gui)

        self.model_path = model_path
        self.hardware_tier = self._detect_hardware_tier()

    def _detect_hardware_tier(self) -> Dict[str, Any]:
        """Detects hardware capabilities and selects the optimal offline SLM tier."""
        mem_stats = self.memory.get_memory_stats()
        ram_mb = mem_stats.get("total_mb", 4000)
        has_gpu = shutil.which("nvidia-smi") is not None

        if ram_mb <= 4500:
            tier = "Tier 1: Ultra-Light (0.5B - 1.5B Q4 GGUF)"
            recommended_model = "qwen2.5-0.5b-instruct.Q4_K_M.gguf"
        elif ram_mb <= 12000:
            tier = "Tier 2: Balanced (3B Q4 GGUF)"
            recommended_model = "qwen2.5-3b-instruct.Q4_K_M.gguf"
        else:
            tier = "Tier 3: High-Performance (7B/8B Q4 GGUF)"
            recommended_model = "qwen2.5-7b-instruct.Q4_K_M.gguf"

        return {
            "ram_total_mb": ram_mb,
            "has_gpu": has_gpu,
            "tier_name": tier,
            "recommended_model": recommended_model,
            "is_low_ram": mem_stats.get("is_low_ram_system", True)
        }

    # ==================== FAST INTENT ROUTER (<2ms) ====================

    def match_fast_intent(self, prompt: str, prompt_cli: bool = False) -> Optional[Dict[str, Any]]:
        """
        Instantly detects and executes standard OS, browser, program, and hardware
        control commands without waiting for LLM token generation.
        """
        p = prompt.strip().lower()

        # 1. Permission Mode Switching
        if any(w in p for w in ["turbo mode", "enable turbo", "activate turbo", "switch to turbo"]):
            new_mode = self.permissions.set_mode("turbo")
            return {
                "thought": "Switched to Turbo Mode (Antigravity-Style). Autonomous execution active without permission prompts.",
                "result": {"mode": new_mode, "status": "active"}
            }

        if any(w in p for w in ["safe mode", "enable safe mode", "activate safe mode", "switch to safe"]):
            new_mode = self.permissions.set_mode("safe")
            return {
                "thought": "Switched to Safe Mode. Explicit user permission will be requested before modifying system, files, or browser.",
                "result": {"mode": new_mode, "status": "active"}
            }

        if p in ["mode", "get mode", "what mode", "current mode"]:
            return {
                "thought": f"Current permission mode: {self.permissions.mode.upper()}",
                "result": {"mode": self.permissions.mode, "is_turbo": self.permissions.is_turbo()}
            }

        # 2. Memory & Housekeeping
        if any(w in p for w in ["clean memory", "free ram", "clean ram", "optimize memory", "drop cache"]):
            return {
                "thought": "Cleaned memory caches and collected runtime garbage.",
                "result": self.memory.clean_memory()
            }

        if any(w in p for w in ["memory stats", "ram stats", "ram usage", "memory usage"]):
            return {
                "thought": "Retrieved system memory statistics.",
                "result": self.memory.get_memory_stats()
            }

        # 3. Audio & Volume
        if "mute" in p:
            if "unmute" in p:
                return {"result": self.system.toggle_mute(state=False), "thought": "Unmuted master audio"}
            return {"result": self.system.toggle_mute(state=True), "thought": "Muted master audio"}

        vol_match = re.search(r"(?:volume|sound)\s*(?:to\s*)?(\d+)\s*%", p) or re.search(r"set\s*volume\s*(?:to\s*)?(\d+)", p)
        if vol_match:
            val = int(vol_match.group(1))
            return {"result": self.system.set_volume(val), "thought": f"Adjusted volume to {val}%"}

        if p in ["volume", "get volume", "what is the volume", "sound level"]:
            return {"result": self.system.get_volume(), "thought": "Retrieved volume level"}

        # 4. Display Brightness
        bright_match = re.search(r"brightness\s*(?:to\s*)?(\d+)\s*%", p) or re.search(r"set\s*brightness\s*(?:to\s*)?(\d+)", p)
        if bright_match:
            val = int(bright_match.group(1))
            return {"result": self.system.set_brightness(val), "thought": f"Adjusted screen brightness to {val}%"}

        if p in ["brightness", "get brightness", "screen brightness"]:
            return {"result": self.system.get_brightness(), "thought": "Retrieved brightness level"}

        # 5. Battery
        if any(w in p for w in ["battery", "battery percentage", "battery level", "power remaining"]):
            return {"result": self.system.get_battery_status(), "thought": "Retrieved battery telemetry"}

        # 6. Wi-Fi & Networking
        if "scan wifi" in p or "list wifi" in p or "available wifi" in p:
            return {"result": self.system.scan_wifi(), "thought": "Scanned nearby Wi-Fi networks"}

        if "wifi status" in p or "network status" in p:
            return {"result": self.system.get_network_status(), "thought": "Retrieved network connection status"}

        # 7. Power Actions (Sensitive)
        if p in ["lock", "lock screen", "lock laptop"]:
            perm = self.permissions.check_permission("power_action", {"action": "lock"}, prompt_cli=prompt_cli)
            if not perm.get("allowed"):
                return {"thought": "Safe Mode: Awaiting user approval to lock screen.", "permission": perm}
            return {"result": self.system.execute_power_action("lock"), "thought": "Locked workstation"}

        if p in ["sleep", "suspend", "sleep laptop"]:
            perm = self.permissions.check_permission("power_action", {"action": "suspend"}, prompt_cli=prompt_cli)
            if not perm.get("allowed"):
                return {"thought": "Safe Mode: Awaiting user approval to suspend laptop.", "permission": perm}
            return {"result": self.system.execute_power_action("suspend"), "thought": "Put laptop to sleep"}

        # 8. Browser Automation
        search_m = re.search(r"(?:search|google|search web for)\s+(.+)", p)
        if search_m and not p.startswith("fetch"):
            query = search_m.group(1).strip()
            return {"result": self.browser.search_web(query), "thought": f"Searched web for '{query}' in desktop browser"}

        open_url_m = re.search(r"(?:open url|open website|browse to|go to)\s+(https?://\S+|\S+\.\S+)", p)
        if open_url_m:
            url = open_url_m.group(1).strip()
            return {"result": self.browser.open_url_in_browser(url), "thought": f"Opened {url} in browser"}

        if p in ["new tab", "open tab"]:
            return {"result": self.browser.new_tab(), "thought": "Opened new browser tab"}

        if p in ["close tab", "close current tab"]:
            return {"result": self.browser.close_current_tab(), "thought": "Closed current browser tab"}

        if any(w in p for w in ["scroll down", "scroll page down"]):
            return {"result": self.browser.scroll_page("down"), "thought": "Scrolled webpage down"}

        if any(w in p for w in ["scroll up", "scroll page up"]):
            return {"result": self.browser.scroll_page("up"), "thought": "Scrolled webpage up"}

        fetch_m = re.search(r"(?:fetch|read page|get content of)\s+(https?://\S+|\S+\.\S+)", p)
        if fetch_m:
            url = fetch_m.group(1).strip()
            return {"result": self.browser.fetch_page_content(url), "thought": f"Fetched content from {url}"}

        # 9. Program Control
        if "nemo" in p or "file manager" in p or "open downloads" in p:
            folder = "~/Downloads" if "downloads" in p else "~"
            return {"result": self.programs.open_directory_in_nemo(folder), "thought": f"Opened Nemo file manager at {folder}"}

        if "vlc" in p:
            if any(w in p for w in ["pause", "play", "toggle"]):
                return {"result": self.programs.control_vlc("play"), "thought": "Toggled VLC playback"}
            if "fullscreen" in p:
                return {"result": self.programs.control_vlc("fullscreen"), "thought": "Toggled VLC fullscreen"}

        writer_m = re.search(r"(?:write document|open writer and type|libreoffice writer)\s+(?:saying\s+|with\s+)?(.+)", p)
        if writer_m:
            text = writer_m.group(1).strip()
            return {
                "result": self.programs.control_libreoffice_writer(text),
                "thought": f"Created new document in LibreOffice Writer with text: '{text[:50]}...'"
            }

        # 10. General App Launch
        launch_m = re.search(r"(?:open|launch|start)\s+(chrome|firefox|terminal|calculator|vlc|libreoffice|gimp)", p)
        if launch_m:
            app = launch_m.group(1)
            return {"result": self.programs.launch_program(app), "thought": f"Launched application '{app}'"}

        # 11. Window & Desktop Control
        if "show desktop" in p or "minimize all" in p:
            return {"result": self.gui.minimize_all_show_desktop(), "thought": "Minimized all windows to show desktop"}

        if p in ["list windows", "open windows", "active windows", "show windows", "running programs"]:
            return {"result": self.gui.list_windows(), "thought": "Listed open desktop windows"}

        focus_m = re.search(r"(?:switch to|focus|bring up)\s+(?:window\s+)?(.+)", p)
        if focus_m:
            win = focus_m.group(1).strip()
            return {"result": self.gui.focus_window(win), "thought": f"Focused window '{win}'"}

        close_m = re.search(r"(?:close window|close app)\s+(.+)", p)
        if close_m:
            win = close_m.group(1).strip()
            return {"result": self.gui.close_window(win), "thought": f"Closed window '{win}'"}

        return None

    # ==================== MAIN COGNITIVE DISPATCH ====================

    def process_command(self, user_prompt: str, prompt_cli: bool = False) -> Dict[str, Any]:
        """
        Processes command through permission checks, fast intent router,
        and local SLM reasoning fallback.
        """
        start_time = time.time()

        # Step 1: Fast Intent
        fast_res = self.match_fast_intent(user_prompt, prompt_cli=prompt_cli)
        if fast_res:
            elapsed = round((time.time() - start_time) * 1000, 2)
            fast_res["latency_ms"] = elapsed
            fast_res["execution_mode"] = "deterministic_sub_millisecond"
            fast_res["permission_mode"] = self.permissions.mode
            return fast_res

        # Step 2: Direct Shell Command Check ($ or !)
        if user_prompt.startswith("!") or user_prompt.startswith("$"):
            cmd = user_prompt[1:].strip()
            perm = self.permissions.check_permission("terminal_execute", {"command": cmd}, prompt_cli=prompt_cli)
            if not perm.get("allowed"):
                return {
                    "thought": f"Safe Mode: Awaiting approval to execute bash command: '{cmd}'",
                    "permission": perm,
                    "execution_mode": "permission_blocked",
                    "latency_ms": round((time.time() - start_time) * 1000, 2)
                }
            return {
                "thought": f"Direct shell execution: {cmd}",
                "result": self.terminal.execute(cmd),
                "execution_mode": "terminal_direct",
                "permission_mode": self.permissions.mode,
                "latency_ms": round((time.time() - start_time) * 1000, 2)
            }

        # Step 3: Local SLM / Reasoning Loop
        slm_res = self._execute_slm_reasoning(user_prompt)
        elapsed = round((time.time() - start_time) * 1000, 2)
        slm_res["latency_ms"] = elapsed
        slm_res["execution_mode"] = "slm_autonomous_planner"
        slm_res["permission_mode"] = self.permissions.mode
        return slm_res

    def _execute_slm_reasoning(self, prompt: str) -> Dict[str, Any]:
        """Executes reasoning using local model backend or safe fallback."""
        if shutil.which("ollama"):
            try:
                import urllib.request
                req_data = json.dumps({
                    "model": "qwen2.5-coder:1.5b",
                    "prompt": f"You are MintPilot, an offline Linux Mint controller agent. User request: '{prompt}'. Return JSON tool call only.",
                    "stream": False
                }).encode('utf-8')
                req = urllib.request.Request("http://127.0.0.1:11434/api/generate", data=req_data, headers={'Content-Type': 'application/json'})
                with urllib.request.urlopen(req, timeout=10) as response:
                    res_body = json.loads(response.read().decode())
                    return {"thought": "Evaluated via local Ollama SLM", "response": res_body.get("response", "")}
            except Exception:
                pass

        return {
            "thought": f"Interpreted request for laptop control: '{prompt}'",
            "memory": self.memory.get_memory_stats(),
            "status": "completed",
            "message": f"Processed: '{prompt}'. Mode: {self.permissions.mode.upper()} | Tier: {self.hardware_tier['tier_name']}"
        }

